        checklist: ['Bottom-up cost model per feature', 'Calls per task measured from traces', 'Hidden traffic (evals, retries, guardrails) included', 'Peak capacity with headroom; quota confirmed', 'Budgets and anomaly alerts', 'Unit economics reported', 'Versioned price table reviewed monthly'],
        sources: ['FinOps Foundation, FinOps for AI guidance (accessed October 2026)', 'OpenAI and Anthropic pricing pages (accessed October 2026; prices change, so examples here are illustrative)', 'Provider documentation on batch APIs and prompt caching (accessed October 2026)'],
